   220	/** Open/closed/overdue counters plus the last write, for the project card. */
   221	export async function getProjectStats(
   222	  orgId: OrgId,
   223	  projectId: ProjectId,
   224	): Promise<ProjectStats> {
   225	  const db = getDb();
   226	  const scope = and(
   227	    orgPredicate(issues.orgId, orgId),
   228	    eq(issues.projectId, projectId),
   229	    ...compact(livePredicate(issues.archivedAt, {})),
   230	  );
   231	
   232	  const closed = db
   233	    .select({ value: count() })
   234	    .from(issues)
   235	    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
   236	    .get();
   237	
   238	  const all = db.select({ value: count() }).from(issues).where(scope).get();
   239	
   240	  const overdue = db
   241	    .select({ value: count() })
   242	    .from(issues)
   243	    .where(
   244	      and(
   245	        scope,
   246	        isNotNull(issues.dueAt),
   247	        lt(issues.dueAt, toIsoTimestamp(new Date())),
   248	      ),
   249	    )
   250	    .get();
   251	
   252	  const lastActivity = db
   253	    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
   254	    .from(issues)
   255	    .where(scope)
   256	    .get();
   257	
   258	  const closedCount = closed?.value ?? 0;
   259	
   260	  return {
   261	    projectId,
   262	    openIssues: (all?.value ?? 0) - closedCount,
   263	    closedIssues: closedCount,
   264	    overdueIssues: overdue?.value ?? 0,
   265	    lastActivityAt:
   266	      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
   267	  };
   268	}
