/**
 * Per-member project mutes. A mute is personal: it is read by the fan-out and
 * the digest, and never by the webhook dispatcher.
 */
import { and, eq } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

export async function isProjectMuted(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<boolean> {
  const row = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .get();
  return row !== undefined;
}

/** Idempotent: muting an already-muted project is a no-op, not a conflict. */
export async function insertProjectMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      mutedAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();
}

export async function deleteProjectMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

