  // A muted project keeps personal kinds in-app only and drops every other kind.
  it("applies the recipient's project mute through the comment fan-out", async () => {
    const owner = tenant.actors.owner;
    const projectId = tenant.project.id;
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, projectId, { title: "Muted fan-out" }),
