      muteProject(tenant.actors.member, tenant.org.id, "prj-missing" as ProjectId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      unmuteProject(tenant.actors.member, other.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

