      limit: 25,
      cursor: null,
    });
    const created = await listNotifications(owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      kind: ["comment_created"],
      limit: 25,
      cursor: null,
    });

    expect(mentions.items).toHaveLength(1);
    expect(mentions.items[0]?.channels).toEqual(["in_app"]);
    expect(mentions.items[0]?.projectId).toBe(projectId);
    expect(created.items).toHaveLength(0);

    await unmuteProject(owner, tenant.org.id, projectId);
    expect(await listMutedProjectIds(owner, tenant.org.id)).toEqual([]);

    const rows = await notify(tenant.org.id, "comment_created", [tenant.userIds.owner], {
      title: "New comment",
      body: "After unmute",
      href: `/issues/${issue.id}`,
      actorId: tenant.userIds.member,
      projectId,
    });
    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app", "email"]);
  });

  // Mutes are guarded like reading the project: same org, project exists there.
  it("guards mute changes like reading the project", async () => {
    const other = await createTenant("mute-other", "growth");

    await expect(
      muteProject(tenant.actors.member, other.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      muteProject(tenant.actors.member, tenant.org.id, "prj-missing" as ProjectId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      unmuteProject(tenant.actors.member, other.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

