it("leaves out muted-project notifications until the project is unmuted", async () => {
  const now = nowAtHour(9);
  const tenant = await makeTenant("digest-muted", 9);
  await subscribeToDigest(tenant);
  await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Muted update", tenant.project.id);
  await insertNotificationAt(tenant, new Date(now.getTime() - 7_200_000), "Open update");

  await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

  const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);

  await runDigestEmailJob(now);

  expect(sendSpy).toHaveBeenCalledTimes(1);
  const muted = sendSpy.mock.calls[0]?.[0].html ?? "";
  expect(cell(muted, "entryCount")).toBe("1");
  expect(cell(muted, "headline")).toBe("Open update");

  await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

  await runDigestEmailJob(now);

  expect(sendSpy).toHaveBeenCalledTimes(2);
  const resurfaced = sendSpy.mock.calls[1]?.[0].html ?? "";
  expect(cell(resurfaced, "entryCount")).toBe("1");
  expect(cell(resurfaced, "headline")).toBe("Muted update");
});

